"use strict";(()=>{const i=window.EyeFitUtils||null;if(!i)throw document.getElementById("main").innerHTML='<div class="section active"><div class="empty-state">\u26A0\uFE0F Error cr\xEDtico: utils.js no carg\xF3.<br>Recarga la p\xE1gina o borra la cach\xE9.</div></div>',new Error("EyeFitUtils missing");const r=(window.EyeFit.Ui||{}).showToast||(e=>{console.error("[EyeFit]",e)});window.addEventListener("error",e=>{console.error("[EyeFit]",e.message||e.error),r("\u26A0\uFE0F Error inesperado: "+(e.message||"desconocido"))});window.addEventListener("unhandledrejection",e=>{const o=e&&e.reason?e.reason.message||e.reason:"desconocido";console.error("[EyeFit] unhandledrejection",o),r("\u26A0\uFE0F Error inesperado: "+o)});window.EyeFit.Bootstrap.init();})();
